def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos] == " ":
            pos += 1

    def parse_atom() -> int | None:
        nonlocal pos
        skip_spaces()
        if expr[pos] == "(":
            pos += 1
            val = parse_expr()
            if val is None:
                return None
            skip_spaces()
            pos += 1
            return val
        start = pos
        while pos < n and "0" <= expr[pos] <= "9":
            pos += 1
        if pos - start <= 4000:
            return int(expr[start:pos])
        val = 0
        for i in range(start, pos, 1000):
            chunk = expr[i : min(i + 1000, pos)]
            val = val * (10 ** len(chunk)) + int(chunk)
        return val

    def parse_unary() -> int | None:
        nonlocal pos
        chain: list[tuple[bool, int]] = []
        while True:
            neg = False
            while pos < n:
                c = expr[pos]
                if c == " ":
                    pos += 1
                elif c == "-":
                    neg = not neg
                    pos += 1
                else:
                    break
            val = parse_atom()
            if val is None:
                return None
            chain.append((neg, val))
            skip_spaces()
            if pos < n and expr[pos] == "^":
                pos += 1
            else:
                break

        neg, acc = chain.pop()
        if neg:
            acc = -acc
        while chain:
            neg, base = chain.pop()
            if acc < 0:
                return None
            if acc == 0:
                res = 1
            elif base == 0:
                res = 0
            elif base == 1:
                res = 1
            elif base == -1:
                res = -1 if (acc & 1) else 1
            else:
                res = base ** acc
            acc = -res if neg else res
        return acc

    def parse_term() -> int | None:
        nonlocal pos
        val = parse_unary()
        if val is None:
            return None
        while True:
            skip_spaces()
            if pos >= n:
                break
            op = expr[pos]
            if op not in ("*", "/", "%"):
                break
            pos += 1
            rhs = parse_unary()
            if rhs is None:
                return None
            if op == "*":
                val *= rhs
            else:
                if rhs == 0:
                    return None
                q = abs(val) // abs(rhs)
                if (val < 0) != (rhs < 0):
                    q = -q
                if op == "/":
                    val = q
                else:
                    val -= rhs * q
        return val

    def parse_expr() -> int | None:
        nonlocal pos
        val = parse_term()
        if val is None:
            return None
        while True:
            skip_spaces()
            if pos >= n:
                break
            op = expr[pos]
            if op not in ("+", "-"):
                break
            pos += 1
            rhs = parse_term()
            if rhs is None:
                return None
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    result = parse_expr()
    return "error" if result is None else result
